using Servicio.RetazoMarket.Business.DTOs.Material;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.Business.Mappers;
public static class MaterialBusinessMapper { public static MaterialDataModel ToDataModel(CrearMaterialRequest r)=>new(){id_categoria=r.id_categoria,mat_nombre=r.mat_nombre.Trim(),unidad_medida=r.unidad_medida.Trim(),stock_actual=r.stock_actual,mat_estado=r.mat_estado.Trim().ToUpperInvariant()}; public static MaterialDataModel ToDataModel(ActualizarMaterialRequest r,decimal stock)=>new(){id_material=r.id_material,id_categoria=r.id_categoria,mat_nombre=r.mat_nombre.Trim(),unidad_medida=r.unidad_medida.Trim(),stock_actual=stock,mat_estado=r.mat_estado.Trim().ToUpperInvariant()}; public static MaterialResponse ToResponse(MaterialDataModel m)=>new(){id_material=m.id_material,id_categoria=m.id_categoria,mat_nombre=m.mat_nombre,unidad_medida=m.unidad_medida,stock_actual=m.stock_actual,mat_estado=m.mat_estado,categoria_nombre=m.Categoria?.cat_nombre}; }
